# Modules 5 and 6, MySQL syntax, one variant per dataset.

M5 = dict(
 id='m05', number=5, phase=2, title='Subqueries: Queries Inside Queries', minutes=240,
 objectives=['Compare rows with a value computed by a scalar subquery', 'Filter with IN and EXISTS against another query',
             'Aggregate first in a derived table, then filter the summary', 'Compare each row with its own group using a correlated subquery'],
 concept_weeks=[5],
 examples=[
  dict(title='Scalar subquery: compare with the average', level='Easy',
       explanation='A subquery that returns one value can sit wherever a number can. The inner query runs first and its answer is used by the outer query.',
       tryIt='Change > to < to see the rows below average.',
       v=dict(sales='SELECT product_name, unit_price\nFROM products\nWHERE unit_price > (SELECT AVG(unit_price) FROM products)\nORDER BY unit_price DESC;',
              sport='SELECT first_name, last_name, market_value_usd\nFROM players\nWHERE market_value_usd > (SELECT AVG(market_value_usd) FROM players)\nORDER BY market_value_usd DESC\nLIMIT 15;',
              fashion='SELECT product_name, retail_price\nFROM products\nWHERE retail_price > (SELECT AVG(retail_price) FROM products)\nORDER BY retail_price DESC;',
              politics='SELECT constituency_name, registered_voters\nFROM constituencies\nWHERE registered_voters > (SELECT AVG(registered_voters) FROM constituencies)\nORDER BY registered_voters DESC;',
              finance='SELECT loan_id, product, principal\nFROM loans\nWHERE principal > (SELECT AVG(principal) FROM loans)\nORDER BY principal DESC\nLIMIT 15;',
              healthcare='SELECT first_name, last_name, consultation_fee\nFROM doctors\nWHERE consultation_fee > (SELECT AVG(consultation_fee) FROM doctors)\nORDER BY consultation_fee DESC;')),
  dict(title='IN (subquery): filter by a list another query builds', level='Easy',
       explanation='IN (SELECT ...) lets one query supply the list of values for another. Read it as "where the id is one of these".',
       tryIt='Use NOT IN to flip the question, and look carefully at what comes back.',
       v=dict(sales="SELECT customer_id, first_name, last_name\nFROM customers\nWHERE customer_id IN (\n    SELECT customer_id FROM orders WHERE status = 'Cancelled'\n);",
              sport='SELECT first_name, last_name, position\nFROM players\nWHERE player_id IN (\n    SELECT player_id FROM goals WHERE is_penalty = 1\n)\nORDER BY last_name;',
              fashion="SELECT product_name, category\nFROM products\nWHERE product_id IN (\n    SELECT l.product_id\n    FROM sale_lines l\n    JOIN returns r ON r.line_id = l.line_id\n    WHERE r.reason = 'Damaged'\n)\nORDER BY product_name;",
              politics='SELECT first_name, last_name, party_id\nFROM candidates\nWHERE candidate_id IN (\n    SELECT candidate_id FROM results WHERE election_id = 2\n);',
              finance="SELECT first_name, last_name, segment\nFROM customers\nWHERE customer_id IN (\n    SELECT customer_id FROM loans WHERE status IN ('Defaulted', 'Written Off')\n)\nORDER BY last_name;",
              healthcare="SELECT first_name, last_name, birth_year\nFROM patients\nWHERE patient_id IN (\n    SELECT a.patient_id\n    FROM appointments a\n    JOIN prescriptions p ON p.appointment_id = a.appointment_id\n    WHERE p.drug_name = 'Metformin'\n)\nORDER BY last_name;")),
  dict(title='Derived table: summarise first, then filter', level='Medium',
       explanation='A subquery in FROM acts as a temporary table. Use it to build a summary, then filter or join that summary like any other table. It must have an alias.',
       tryIt='Join the derived table to the names table so each row shows a name.',
       v=dict(sales='SELECT t.customer_id, t.num_orders\nFROM (\n    SELECT customer_id, COUNT(*) AS num_orders\n    FROM orders\n    GROUP BY customer_id\n) AS t\nWHERE t.num_orders > 3\nORDER BY t.num_orders DESC;',
              sport='SELECT t.player_id, t.goals\nFROM (\n    SELECT player_id, COUNT(*) AS goals\n    FROM goals\n    GROUP BY player_id\n) AS t\nWHERE t.goals >= 10\nORDER BY t.goals DESC;',
              fashion='SELECT t.customer_id, t.purchases\nFROM (\n    SELECT customer_id, COUNT(*) AS purchases\n    FROM sales\n    WHERE customer_id IS NOT NULL\n    GROUP BY customer_id\n) AS t\nWHERE t.purchases >= 10\nORDER BY t.purchases DESC;',
              politics='SELECT t.candidate_id, t.total_votes\nFROM (\n    SELECT candidate_id, SUM(votes) AS total_votes\n    FROM results\n    GROUP BY candidate_id\n) AS t\nWHERE t.total_votes > 20000\nORDER BY t.total_votes DESC;',
              finance='SELECT t.customer_id, t.num_loans\nFROM (\n    SELECT customer_id, COUNT(*) AS num_loans\n    FROM loans\n    GROUP BY customer_id\n) AS t\nWHERE t.num_loans >= 3\nORDER BY t.customer_id;',
              healthcare='SELECT t.patient_id, t.visits\nFROM (\n    SELECT patient_id, COUNT(*) AS visits\n    FROM appointments\n    GROUP BY patient_id\n) AS t\nWHERE t.visits >= 12\nORDER BY t.visits DESC;')),
  dict(title='Correlated subquery: compare with your own group', level='Medium',
       explanation='The inner query refers to the outer row, so it gets a fresh answer for every row. Use it for "above the average of its own group" questions.',
       tryIt='Compare with MAX instead of AVG and see which rows survive.',
       v=dict(sales='SELECT p.product_name, p.category_id, p.unit_price\nFROM products p\nWHERE p.unit_price > (\n    SELECT AVG(p2.unit_price)\n    FROM products p2\n    WHERE p2.category_id = p.category_id\n)\nORDER BY p.category_id, p.unit_price DESC;',
              sport='SELECT p.first_name, p.last_name, p.team_id, p.market_value_usd\nFROM players p\nWHERE p.market_value_usd > (\n    SELECT AVG(p2.market_value_usd)\n    FROM players p2\n    WHERE p2.team_id = p.team_id\n)\n  AND p.team_id = 1\nORDER BY p.market_value_usd DESC;',
              fashion='SELECT p.product_name, p.category, p.retail_price\nFROM products p\nWHERE p.retail_price > (\n    SELECT AVG(p2.retail_price)\n    FROM products p2\n    WHERE p2.category = p.category\n)\nORDER BY p.category, p.retail_price DESC;',
              politics='SELECT c.constituency_name, c.region_id, c.registered_voters\nFROM constituencies c\nWHERE c.registered_voters > (\n    SELECT AVG(c2.registered_voters)\n    FROM constituencies c2\n    WHERE c2.region_id = c.region_id\n)\nORDER BY c.region_id, c.registered_voters DESC;',
              finance="SELECT l.loan_id, l.product, l.principal\nFROM loans l\nWHERE l.principal > (\n    SELECT AVG(l2.principal)\n    FROM loans l2\n    WHERE l2.product = l.product\n)\n  AND l.disbursed_date >= '2025-07-01'\nORDER BY l.product, l.principal DESC;",
              healthcare='SELECT d.first_name, d.last_name, d.department_id, d.consultation_fee\nFROM doctors d\nWHERE d.consultation_fee > (\n    SELECT AVG(d2.consultation_fee)\n    FROM doctors d2\n    WHERE d2.department_id = d.department_id\n)\nORDER BY d.department_id;')),
  dict(title='EXISTS and NOT EXISTS', level='Medium',
       explanation='EXISTS only asks whether at least one matching row exists, so it can stop at the first match. NOT EXISTS finds rows with no match, and unlike NOT IN it is safe when the other table has NULLs.',
       tryIt='Swap EXISTS for NOT EXISTS.',
       v=dict(sales="SELECT c.customer_id, c.first_name, c.last_name\nFROM customers c\nWHERE NOT EXISTS (\n    SELECT 1 FROM orders o WHERE o.customer_id = c.customer_id\n);",
              sport="SELECT t.team_name\nFROM teams t\nWHERE NOT EXISTS (\n    SELECT 1 FROM players p WHERE p.team_id = t.team_id\n);",
              fashion="SELECT c.customer_id, c.first_name, c.last_name\nFROM customers c\nWHERE NOT EXISTS (\n    SELECT 1 FROM sales s WHERE s.customer_id = c.customer_id\n);",
              politics="SELECT p.party_name\nFROM parties p\nWHERE NOT EXISTS (\n    SELECT 1 FROM candidates c WHERE c.party_id = p.party_id\n);",
              finance="SELECT b.branch_name\nFROM branches b\nWHERE EXISTS (\n    SELECT 1\n    FROM customers c\n    JOIN loans l ON l.customer_id = c.customer_id\n    WHERE c.branch_id = b.branch_id AND l.status = 'Written Off'\n);",
              healthcare="SELECT p.patient_id, p.first_name, p.last_name\nFROM patients p\nWHERE NOT EXISTS (\n    SELECT 1 FROM appointments a WHERE a.patient_id = p.patient_id\n);")),
 ],
 exercises=[
  dict(level='Easy', concepts=['Scalar subquery'], order=True,
       hint2='Write the average as its own query in brackets, (SELECT AVG(column) FROM table), and compare against it in WHERE.',
       explain='The subquery works out one number, the average, and the outer WHERE keeps every row above it. The average is recalculated if the data changes, so nothing is hard-coded.',
       v=dict(
        sales=('Merchandising wants the products that cost more than a typical product.', 'List products priced above the average unit price. Return product name and unit price, most expensive first, then product name.', ['product_name', 'unit_price'], 'SELECT product_name, unit_price\nFROM products\nWHERE unit_price > (SELECT AVG(unit_price) FROM products)\nORDER BY unit_price DESC, product_name;'),
        sport=('A scout wants forwards who are worth more than a typical forward.', "List forwards ('FW') valued above the average forward's market value. Return first name, last name and market value, highest first, then last name, then first name.", ['first_name', 'last_name', 'market_value_usd'], "SELECT first_name, last_name, market_value_usd\nFROM players\nWHERE position = 'FW'\n  AND market_value_usd > (SELECT AVG(market_value_usd) FROM players WHERE position = 'FW')\nORDER BY market_value_usd DESC, last_name, first_name;"),
        fashion=('The buying team wants the products priced above a typical product.', 'List products priced above the average retail price. Return product name and retail price, most expensive first, then product name.', ['product_name', 'retail_price'], 'SELECT product_name, retail_price\nFROM products\nWHERE retail_price > (SELECT AVG(retail_price) FROM products)\nORDER BY retail_price DESC, product_name;'),
        politics=('The commission is checking which seats are bigger than a typical seat.', 'List constituencies with more registered voters than the average constituency. Return constituency name and registered voters, largest first.', ['constituency_name', 'registered_voters'], 'SELECT constituency_name, registered_voters\nFROM constituencies\nWHERE registered_voters > (SELECT AVG(registered_voters) FROM constituencies)\nORDER BY registered_voters DESC;'),
        finance=('The SME desk wants its larger-than-usual loans.', "List 'SME Working Capital' loans with a principal above the average principal of that product. Return loan id and principal, largest first, then loan id.", ['loan_id', 'principal'], "SELECT loan_id, principal\nFROM loans\nWHERE product = 'SME Working Capital'\n  AND principal > (SELECT AVG(principal) FROM loans WHERE product = 'SME Working Capital')\nORDER BY principal DESC, loan_id;"),
        healthcare=('Finance wants doctors who charge more than a typical doctor.', 'List doctors whose consultation fee is above the average fee of all doctors. Return first name, last name and consultation fee, highest first, then last name.', ['first_name', 'last_name', 'consultation_fee'], 'SELECT first_name, last_name, consultation_fee\nFROM doctors\nWHERE consultation_fee > (SELECT AVG(consultation_fee) FROM doctors)\nORDER BY consultation_fee DESC, last_name;'))),
  dict(level='Easy', concepts=['EXISTS'], order=True,
       hint2='WHERE EXISTS (SELECT 1 FROM other_table WHERE other_table.key = outer_table.key AND ...) keeps rows that have at least one match.',
       explain='EXISTS checks each outer row for at least one matching row in the subquery. It returns each outer row once, however many matches it has, so no DISTINCT is needed.',
       v=dict(
        sales=('Customer success wants everyone who has ordered at least once.', 'Using EXISTS, list customers who have placed at least one order. Return customer id, first name and last name, sorted by customer id.', ['customer_id', 'first_name', 'last_name'], 'SELECT c.customer_id, c.first_name, c.last_name\nFROM customers c\nWHERE EXISTS (\n    SELECT 1 FROM orders o WHERE o.customer_id = c.customer_id\n)\nORDER BY c.customer_id;'),
        sport=('The Nigerian federation wants to know which clubs it should scout.', "Using EXISTS, list teams that have at least one player whose nationality is 'Nigeria'. Return team name, sorted A to Z.", ['team_name'], "SELECT t.team_name\nFROM teams t\nWHERE EXISTS (\n    SELECT 1 FROM players p\n    WHERE p.team_id = t.team_id AND p.nationality = 'Nigeria'\n)\nORDER BY t.team_name;"),
        fashion=('The footwear buyer wants brands that make shoes.', "Using EXISTS, list brands that have at least one product in the 'Shoes' category (products link to brands through collections). Return brand name, A to Z.", ['brand_name'], "SELECT b.brand_name\nFROM brands b\nWHERE EXISTS (\n    SELECT 1\n    FROM collections c\n    JOIN products p ON p.collection_id = c.collection_id\n    WHERE c.brand_id = b.brand_id AND p.category = 'Shoes'\n)\nORDER BY b.brand_name;"),
        politics=('The commission is sending extra staff to regions with very large seats.', 'Using EXISTS, list regions that have at least one constituency with more than 90,000 registered voters. Return region name, A to Z.', ['region_name'], 'SELECT r.region_name\nFROM regions r\nWHERE EXISTS (\n    SELECT 1 FROM constituencies c\n    WHERE c.region_id = r.region_id AND c.registered_voters > 90000\n)\nORDER BY r.region_name;'),
        finance=('Recoveries wants branches with at least one problem loan.', "Using EXISTS, list branches with at least one customer whose loan status is 'Defaulted' or 'Written Off'. Return branch name, A to Z.", ['branch_name'], "SELECT b.branch_name\nFROM branches b\nWHERE EXISTS (\n    SELECT 1\n    FROM customers c\n    JOIN loans l ON l.customer_id = c.customer_id\n    WHERE c.branch_id = b.branch_id\n      AND l.status IN ('Defaulted', 'Written Off')\n)\nORDER BY b.branch_name;"),
        healthcare=('Operations wants departments that had a no-show in December 2025.', "Using EXISTS, list departments with at least one 'No-show' appointment scheduled in December 2025. Return department name, A to Z.", ['department_name'], "SELECT dp.department_name\nFROM departments dp\nWHERE EXISTS (\n    SELECT 1\n    FROM doctors d\n    JOIN appointments a ON a.doctor_id = d.doctor_id\n    WHERE d.department_id = dp.department_id\n      AND a.status = 'No-show'\n      AND a.scheduled_at >= '2025-12-01' AND a.scheduled_at < '2026-01-01'\n)\nORDER BY dp.department_name;"))),
  dict(level='Medium', concepts=['Correlated subquery'], order=True,
       hint2='Give the outer table one alias and the inner table another. In the inner WHERE, link the two aliases on the group column so the average is worked out for that row\'s own group.',
       explain='The inner query is re-run for every outer row, each time using that row\'s group. That is why each row is compared with its own group and not with everyone.',
       v=dict(
        sales=('HR is auditing pay against reporting lines.', 'Using a correlated subquery, find employees who earn more than their own manager. Return employee name (first and last), their salary and their manager\'s salary.', ['employee_name', 'salary', 'manager_salary'], "SELECT CONCAT(e.first_name, ' ', e.last_name) AS employee_name,\n       e.salary,\n       (SELECT m.salary FROM employees m WHERE m.employee_id = e.manager_id) AS manager_salary\nFROM employees e\nWHERE e.salary > (\n    SELECT m.salary FROM employees m WHERE m.employee_id = e.manager_id\n);"),
        sport=('Each club wants to know its standout players.', 'Using a correlated subquery, list players valued at more than twice their own team\'s average market value. Return first name, last name, team id and market value, highest value first, then last name.', ['first_name', 'last_name', 'team_id', 'market_value_usd'], 'SELECT p.first_name, p.last_name, p.team_id, p.market_value_usd\nFROM players p\nWHERE p.market_value_usd > 2 * (\n    SELECT AVG(p2.market_value_usd)\n    FROM players p2\n    WHERE p2.team_id = p.team_id\n)\nORDER BY p.market_value_usd DESC, p.last_name;'),
        fashion=('Each category buyer wants their premium lines.', 'Using a correlated subquery, list products priced above the average retail price of their own category. Return product name, category and retail price, sorted by category, then price highest first, then product name.', ['product_name', 'category', 'retail_price'], 'SELECT p.product_name, p.category, p.retail_price\nFROM products p\nWHERE p.retail_price > (\n    SELECT AVG(p2.retail_price)\n    FROM products p2\n    WHERE p2.category = p.category\n)\nORDER BY p.category, p.retail_price DESC, p.product_name;'),
        politics=('Regional offices want to know their largest seats.', 'Using a correlated subquery, list constituencies with more registered voters than the average of their own region. Return constituency name, region id and registered voters, sorted by region id, then voters, largest first.', ['constituency_name', 'region_id', 'registered_voters'], 'SELECT c.constituency_name, c.region_id, c.registered_voters\nFROM constituencies c\nWHERE c.registered_voters > (\n    SELECT AVG(c2.registered_voters)\n    FROM constituencies c2\n    WHERE c2.region_id = c.region_id\n)\nORDER BY c.region_id, c.registered_voters DESC;'),
        finance=('Credit wants this year\'s unusually large loans for each product.', "Using a correlated subquery, list loans disbursed on or after 2025-01-01 whose principal is more than 1.5 times the average principal of the same product (across all years). Return loan id, product and principal, largest first, then loan id.", ['loan_id', 'product', 'principal'], "SELECT l.loan_id, l.product, l.principal\nFROM loans l\nWHERE l.disbursed_date >= '2025-01-01'\n  AND l.principal > 1.5 * (\n    SELECT AVG(l2.principal)\n    FROM loans l2\n    WHERE l2.product = l.product\n)\nORDER BY l.principal DESC, l.loan_id;"),
        healthcare=('The medical director is reviewing fees inside each department.', 'Using a correlated subquery, list doctors whose consultation fee is above the average fee of their own department. Return first name, last name, department id and consultation fee, sorted by department id, then last name.', ['first_name', 'last_name', 'department_id', 'consultation_fee'], 'SELECT d.first_name, d.last_name, d.department_id, d.consultation_fee\nFROM doctors d\nWHERE d.consultation_fee > (\n    SELECT AVG(d2.consultation_fee)\n    FROM doctors d2\n    WHERE d2.department_id = d.department_id\n)\nORDER BY d.department_id, d.last_name;'))),
  dict(level='Medium', concepts=['Subquery in HAVING', 'Derived table'], order=True,
       hint2='Build the totals in a derived table, take MAX of that total in a subquery, and keep only the group whose total equals it with HAVING.',
       explain='The innermost query builds a total per item, the next level takes the largest of those totals, and HAVING keeps the item or items whose total equals it. Ties are all returned, which a plain ORDER BY ... LIMIT 1 would hide.',
       v=dict(
        sales=('The warehouse wants the single best-selling product.', 'Find the product or products with the highest total quantity sold. Return product name and units_sold. If several tie, show them all, sorted by product name.', ['product_name', 'units_sold'], 'SELECT p.product_name, SUM(oi.quantity) AS units_sold\nFROM products p\nJOIN order_items oi ON oi.product_id = p.product_id\nGROUP BY p.product_id, p.product_name\nHAVING SUM(oi.quantity) = (\n    SELECT MAX(t.units)\n    FROM (SELECT SUM(quantity) AS units FROM order_items GROUP BY product_id) AS t\n)\nORDER BY p.product_name;'),
        sport=("The league is presenting the golden boot.", 'Find the player or players with the most goals across both seasons. Return first name, last name and goals. If several tie, show them all, sorted by last name.', ['first_name', 'last_name', 'goals'], 'SELECT p.first_name, p.last_name, COUNT(*) AS goals\nFROM players p\nJOIN goals g ON g.player_id = p.player_id\nGROUP BY p.player_id, p.first_name, p.last_name\nHAVING COUNT(*) = (\n    SELECT MAX(t.n)\n    FROM (SELECT COUNT(*) AS n FROM goals GROUP BY player_id) AS t\n)\nORDER BY p.last_name;'),
        fashion=('The buying team wants the single best-selling product.', 'Find the product or products with the highest total quantity sold. Return product name and units_sold. If several tie, show them all, sorted by product name.', ['product_name', 'units_sold'], 'SELECT p.product_name, SUM(l.qty) AS units_sold\nFROM products p\nJOIN sale_lines l ON l.product_id = p.product_id\nGROUP BY p.product_id, p.product_name\nHAVING SUM(l.qty) = (\n    SELECT MAX(t.units)\n    FROM (SELECT SUM(qty) AS units FROM sale_lines GROUP BY product_id) AS t\n)\nORDER BY p.product_name;'),
        politics=('A reporter wants the most popular candidate of the 2025 general election.', 'For election 3, find the candidate or candidates with the highest vote total. Return first name, last name and total_votes. If several tie, show them all.', ['first_name', 'last_name', 'total_votes'], 'SELECT c.first_name, c.last_name, SUM(r.votes) AS total_votes\nFROM candidates c\nJOIN results r ON r.candidate_id = c.candidate_id\nWHERE r.election_id = 3\nGROUP BY c.candidate_id, c.first_name, c.last_name\nHAVING SUM(r.votes) = (\n    SELECT MAX(t.v)\n    FROM (SELECT SUM(votes) AS v FROM results WHERE election_id = 3 GROUP BY candidate_id) AS t\n)\nORDER BY c.last_name;'),
        finance=('Risk wants the customer who has borrowed the most in total.', 'Find the customer or customers with the highest total principal across all their loans. Return first name, last name and total_principal. If several tie, show them all, sorted by last name.', ['first_name', 'last_name', 'total_principal'], 'SELECT c.first_name, c.last_name, SUM(l.principal) AS total_principal\nFROM customers c\nJOIN loans l ON l.customer_id = c.customer_id\nGROUP BY c.customer_id, c.first_name, c.last_name\nHAVING SUM(l.principal) = (\n    SELECT MAX(t.total)\n    FROM (SELECT SUM(principal) AS total FROM loans GROUP BY customer_id) AS t\n)\nORDER BY c.last_name;'),
        healthcare=('Pharmacy wants its most prescribed drug.', 'Find the drug or drugs prescribed the most times. Return drug name and times_prescribed. If several tie, show them all, sorted by drug name.', ['drug_name', 'times_prescribed'], 'SELECT drug_name, COUNT(*) AS times_prescribed\nFROM prescriptions\nGROUP BY drug_name\nHAVING COUNT(*) = (\n    SELECT MAX(t.n)\n    FROM (SELECT COUNT(*) AS n FROM prescriptions GROUP BY drug_name) AS t\n)\nORDER BY drug_name;'))),
  dict(level='Hard', concepts=['Derived table', 'Scalar subquery', 'JOIN'], order=True,
       hint2='Build each item\'s total in a derived table. Compare each total with (SELECT AVG(total) FROM (the same derived table) AS x). Join to the names table for the output.',
       explain='There are two levels of summary: a total per item, then the average of those totals. Comparing the first with the second answers "above a typical customer", which an average over raw rows would get wrong.',
       v=dict(
        sales=('Marketing wants its above-average customers.', 'Find customers whose total spend (quantity x unit price x (1 - discount)) is above the average total spend per customer. Return customer name (first and last) and total_spend rounded to 2 decimals, highest first.', ['customer_name', 'total_spend'], "SELECT CONCAT(c.first_name, ' ', c.last_name) AS customer_name,\n       ROUND(t.total_spend, 2) AS total_spend\nFROM (\n    SELECT o.customer_id, SUM(oi.quantity * oi.unit_price * (1 - oi.discount)) AS total_spend\n    FROM orders o\n    JOIN order_items oi ON oi.order_id = o.order_id\n    GROUP BY o.customer_id\n) AS t\nJOIN customers c ON c.customer_id = t.customer_id\nWHERE t.total_spend > (\n    SELECT AVG(x.total_spend)\n    FROM (\n        SELECT o.customer_id, SUM(oi.quantity * oi.unit_price * (1 - oi.discount)) AS total_spend\n        FROM orders o\n        JOIN order_items oi ON oi.order_id = o.order_id\n        GROUP BY o.customer_id\n    ) AS x\n)\nORDER BY total_spend DESC;"),
        sport=('The awards panel wants scorers well above the norm.', 'Among players who have scored, find those whose total goals are above the average goals per scorer. Return player name (first and last) and goals, most first, then player name.', ['player_name', 'goals'], "SELECT CONCAT(p.first_name, ' ', p.last_name) AS player_name, t.goals\nFROM (\n    SELECT player_id, COUNT(*) AS goals FROM goals GROUP BY player_id\n) AS t\nJOIN players p ON p.player_id = t.player_id\nWHERE t.goals > (\n    SELECT AVG(x.goals)\n    FROM (SELECT player_id, COUNT(*) AS goals FROM goals GROUP BY player_id) AS x\n)\nORDER BY t.goals DESC, player_name;"),
        fashion=('The loyalty team wants its above-average spenders from 2025.', "Using sales on or after 2025-01-01 with a customer, find customers whose total 2025 spend (qty x unit price x (1 - discount)) is above the average 2025 spend per customer. Return customer name (first and last) and spend_2025 rounded to 2 decimals, highest first.", ['customer_name', 'spend_2025'], "SELECT CONCAT(c.first_name, ' ', c.last_name) AS customer_name,\n       ROUND(t.spend, 2) AS spend_2025\nFROM (\n    SELECT s.customer_id, SUM(l.qty * l.unit_price * (1 - l.discount)) AS spend\n    FROM sales s\n    JOIN sale_lines l ON l.sale_id = s.sale_id\n    WHERE s.customer_id IS NOT NULL AND s.sale_date >= '2025-01-01'\n    GROUP BY s.customer_id\n) AS t\nJOIN customers c ON c.customer_id = t.customer_id\nWHERE t.spend > (\n    SELECT AVG(x.spend)\n    FROM (\n        SELECT s.customer_id, SUM(l.qty * l.unit_price * (1 - l.discount)) AS spend\n        FROM sales s\n        JOIN sale_lines l ON l.sale_id = s.sale_id\n        WHERE s.customer_id IS NOT NULL AND s.sale_date >= '2025-01-01'\n        GROUP BY s.customer_id\n    ) AS x\n)\nORDER BY spend_2025 DESC;"),
        politics=('The commission wants seats where turnout was above the norm in 2025.', 'For election 3, find constituencies whose total votes cast are above the average total per constituency. Return constituency name and total_votes, most first.', ['constituency_name', 'total_votes'], 'SELECT k.constituency_name, t.total_votes\nFROM (\n    SELECT constituency_id, SUM(votes) AS total_votes\n    FROM results WHERE election_id = 3\n    GROUP BY constituency_id\n) AS t\nJOIN constituencies k ON k.constituency_id = t.constituency_id\nWHERE t.total_votes > (\n    SELECT AVG(x.total_votes)\n    FROM (SELECT constituency_id, SUM(votes) AS total_votes FROM results WHERE election_id = 3 GROUP BY constituency_id) AS x\n)\nORDER BY t.total_votes DESC;'),
        finance=('Risk wants its heaviest SME borrowers.', "For customers in the 'SME' segment, find those whose total principal borrowed is above the average total per SME borrower. Return customer name (first and last) and total_principal, largest first, then customer name.", ['customer_name', 'total_principal'], "SELECT CONCAT(c.first_name, ' ', c.last_name) AS customer_name, t.total_principal\nFROM (\n    SELECT l.customer_id, SUM(l.principal) AS total_principal\n    FROM loans l JOIN customers c2 ON c2.customer_id = l.customer_id\n    WHERE c2.segment = 'SME'\n    GROUP BY l.customer_id\n) AS t\nJOIN customers c ON c.customer_id = t.customer_id\nWHERE t.total_principal > (\n    SELECT AVG(x.total_principal)\n    FROM (\n        SELECT l.customer_id, SUM(l.principal) AS total_principal\n        FROM loans l JOIN customers c2 ON c2.customer_id = l.customer_id\n        WHERE c2.segment = 'SME'\n        GROUP BY l.customer_id\n    ) AS x\n)\nORDER BY t.total_principal DESC, customer_name;"),
        healthcare=('Pharmacy wants patients with above-average medicine costs.', 'Find patients whose total prescription cost is above the average total per patient (count only patients who have prescriptions). Return patient name (first and last) and total_cost rounded to 2 decimals. Show the top 15, highest first, then patient name.', ['patient_name', 'total_cost'], "SELECT CONCAT(p.first_name, ' ', p.last_name) AS patient_name,\n       ROUND(t.total_cost, 2) AS total_cost\nFROM (\n    SELECT a.patient_id, SUM(rx.cost) AS total_cost\n    FROM appointments a\n    JOIN prescriptions rx ON rx.appointment_id = a.appointment_id\n    GROUP BY a.patient_id\n) AS t\nJOIN patients p ON p.patient_id = t.patient_id\nWHERE t.total_cost > (\n    SELECT AVG(x.total_cost)\n    FROM (\n        SELECT a.patient_id, SUM(rx.cost) AS total_cost\n        FROM appointments a\n        JOIN prescriptions rx ON rx.appointment_id = a.appointment_id\n        GROUP BY a.patient_id\n    ) AS x\n)\nORDER BY total_cost DESC, patient_name\nLIMIT 15;"))),
 ])

M6 = dict(
 id='m06', number=6, phase=2, title='CTEs, Set Operations and Recursive Queries', minutes=240,
 objectives=['Name a step of a query with WITH', 'Chain CTEs to build an answer in small, testable pieces',
             'Stack and compare result sets with UNION, INTERSECT and EXCEPT', 'Walk a hierarchy with a recursive CTE'],
 concept_weeks=[6],
 examples=[
  dict(title='A CTE names a step', level='Easy',
       explanation='WITH name AS (...) defines a temporary result you can query by name. The query then reads top to bottom instead of inside out.',
       tryIt='Change the threshold in the final WHERE.',
       v=dict(sales='WITH order_revenue AS (\n    SELECT order_id, SUM(quantity * unit_price * (1 - discount)) AS revenue\n    FROM order_items\n    GROUP BY order_id\n)\nSELECT order_id, ROUND(revenue, 2) AS revenue\nFROM order_revenue\nWHERE revenue > 1000\nORDER BY revenue DESC;',
              sport='WITH match_goals AS (\n    SELECT match_id, match_date, home_goals + away_goals AS total_goals\n    FROM matches\n)\nSELECT match_id, match_date, total_goals\nFROM match_goals\nWHERE total_goals >= 6\nORDER BY total_goals DESC, match_date;',
              fashion='WITH sale_revenue AS (\n    SELECT sale_id, SUM(qty * unit_price * (1 - discount)) AS revenue\n    FROM sale_lines\n    GROUP BY sale_id\n)\nSELECT sale_id, ROUND(revenue, 2) AS revenue\nFROM sale_revenue\nWHERE revenue > 500\nORDER BY revenue DESC;',
              politics='WITH party_votes AS (\n    SELECT c.party_id, SUM(r.votes) AS votes\n    FROM results r\n    JOIN candidates c ON c.candidate_id = r.candidate_id\n    WHERE r.election_id = 3\n    GROUP BY c.party_id\n)\nSELECT party_id, votes\nFROM party_votes\nORDER BY votes DESC;',
              finance='WITH repaid AS (\n    SELECT loan_id, SUM(amount_paid) AS total_repaid\n    FROM repayments\n    GROUP BY loan_id\n)\nSELECT loan_id, ROUND(total_repaid, 2) AS total_repaid\nFROM repaid\nWHERE total_repaid > 3000000\nORDER BY total_repaid DESC;',
              healthcare='WITH visit_cost AS (\n    SELECT appointment_id, SUM(cost) AS medicine_cost\n    FROM prescriptions\n    GROUP BY appointment_id\n)\nSELECT appointment_id, ROUND(medicine_cost, 2) AS medicine_cost\nFROM visit_cost\nWHERE medicine_cost > 50\nORDER BY medicine_cost DESC;')),
  dict(title='Chain several CTEs', level='Medium',
       explanation='Separate CTEs with commas. A later CTE can read an earlier one, so each step stays small enough to test on its own.',
       tryIt='Select from the first CTE only, to check that step on its own.',
       v=dict(sales='WITH customer_spend AS (\n    SELECT o.customer_id, SUM(oi.quantity * oi.unit_price * (1 - oi.discount)) AS spend\n    FROM orders o JOIN order_items oi ON oi.order_id = o.order_id\n    GROUP BY o.customer_id\n),\naverage AS (\n    SELECT AVG(spend) AS avg_spend FROM customer_spend\n)\nSELECT cs.customer_id, ROUND(cs.spend, 2) AS spend, ROUND(a.avg_spend, 2) AS avg_spend\nFROM customer_spend cs\nCROSS JOIN average a\nWHERE cs.spend > a.avg_spend\nORDER BY cs.spend DESC;',
              sport='WITH scorer AS (\n    SELECT player_id, COUNT(*) AS goals FROM goals GROUP BY player_id\n),\nleague AS (\n    SELECT AVG(goals) AS avg_goals FROM scorer\n)\nSELECT s.player_id, s.goals, ROUND(l.avg_goals, 1) AS avg_goals\nFROM scorer s CROSS JOIN league l\nWHERE s.goals >= 2 * l.avg_goals\nORDER BY s.goals DESC;',
              fashion='WITH store_rev AS (\n    SELECT s.store_id, SUM(l.qty * l.unit_price * (1 - l.discount)) AS revenue\n    FROM sales s JOIN sale_lines l ON l.sale_id = s.sale_id\n    GROUP BY s.store_id\n),\ntotal AS (\n    SELECT SUM(revenue) AS all_revenue FROM store_rev\n)\nSELECT sr.store_id, ROUND(sr.revenue, 2) AS revenue,\n       ROUND(100.0 * sr.revenue / t.all_revenue, 1) AS pct\nFROM store_rev sr CROSS JOIN total t\nORDER BY sr.revenue DESC;',
              politics='WITH turnout AS (\n    SELECT constituency_id, SUM(votes) AS votes\n    FROM results WHERE election_id = 3\n    GROUP BY constituency_id\n),\nwith_voters AS (\n    SELECT t.constituency_id, t.votes, k.registered_voters\n    FROM turnout t JOIN constituencies k ON k.constituency_id = t.constituency_id\n)\nSELECT constituency_id, votes, registered_voters,\n       ROUND(100.0 * votes / registered_voters, 1) AS turnout_pct\nFROM with_voters\nORDER BY turnout_pct DESC\nLIMIT 10;',
              finance='WITH due AS (\n    SELECT loan_id, SUM(amount_due) AS total_due, SUM(amount_paid) AS total_paid\n    FROM repayments GROUP BY loan_id\n),\ngap AS (\n    SELECT loan_id, total_due - total_paid AS arrears FROM due\n)\nSELECT loan_id, ROUND(arrears, 2) AS arrears\nFROM gap\nWHERE arrears > 0\nORDER BY arrears DESC\nLIMIT 15;',
              healthcare="WITH dept_visits AS (\n    SELECT d.department_id, COUNT(*) AS visits, AVG(a.wait_minutes) AS avg_wait\n    FROM appointments a JOIN doctors d ON d.doctor_id = a.doctor_id\n    WHERE a.status = 'Completed'\n    GROUP BY d.department_id\n),\noverall AS (\n    SELECT AVG(wait_minutes) AS clinic_avg FROM appointments WHERE status = 'Completed'\n)\nSELECT dv.department_id, dv.visits, ROUND(dv.avg_wait, 1) AS avg_wait, ROUND(o.clinic_avg, 1) AS clinic_avg\nFROM dept_visits dv CROSS JOIN overall o\nORDER BY dv.avg_wait DESC;")),
  dict(title='UNION and UNION ALL stack results', level='Easy',
       explanation='UNION puts the rows of two queries in one list and removes duplicates; UNION ALL keeps every row and is faster. Both queries need the same number of columns, in the same order.',
       tryIt='Switch UNION ALL to UNION and look for rows that collapse.',
       v=dict(sales="SELECT product_name, 'Premium' AS flag FROM products WHERE unit_price > 150\nUNION ALL\nSELECT product_name, 'Low stock' FROM products WHERE stock_quantity < 40\nORDER BY product_name;",
              sport="SELECT CONCAT(first_name, ' ', last_name) AS person, 'Player' AS kind FROM players WHERE team_id = 1\nUNION ALL\nSELECT CONCAT(first_name, ' ', last_name), role FROM staff WHERE team_id = 1\nORDER BY kind, person;",
              fashion="SELECT CONCAT(first_name, ' ', last_name) AS person, 'Staff' AS kind FROM staff WHERE store_id = 3\nUNION ALL\nSELECT CONCAT(first_name, ' ', last_name), 'Customer' FROM customers WHERE city = 'Accra'\nORDER BY kind, person;",
              politics="SELECT election_date AS event_date, election_name AS event FROM elections\nUNION ALL\nSELECT CONCAT(founded_year, '-01-01'), CONCAT(party_name, ' founded') FROM parties WHERE founded_year >= 2000\nORDER BY event_date;",
              finance="SELECT CONCAT(first_name, ' ', last_name) AS person, 'Customer' AS kind FROM customers WHERE branch_id = 8\nUNION ALL\nSELECT CONCAT(first_name, ' ', last_name), role FROM employees WHERE branch_id = 8\nORDER BY kind, person;",
              healthcare="SELECT CONCAT('Dr ', last_name) AS person, 'Doctor' AS kind FROM doctors WHERE department_id = 3\nUNION ALL\nSELECT CONCAT(p.first_name, ' ', p.last_name), 'Patient'\nFROM patients p\nWHERE p.patient_id IN (SELECT a.patient_id FROM appointments a WHERE a.doctor_id IN (SELECT doctor_id FROM doctors WHERE department_id = 3) AND a.scheduled_at >= '2025-12-01')\nORDER BY kind, person;")),
  dict(title='INTERSECT and EXCEPT compare two sets', level='Medium',
       explanation='INTERSECT keeps rows found in both queries. EXCEPT keeps rows from the first query that are not in the second. MySQL supports both from version 8.0.31.',
       tryIt='Swap INTERSECT for EXCEPT and read the question it now answers.',
       v=dict(sales="SELECT customer_id FROM orders WHERE status = 'Completed'\nEXCEPT\nSELECT customer_id FROM orders WHERE status = 'Cancelled'\nORDER BY customer_id;",
              sport='SELECT g.player_id FROM goals g JOIN matches m ON m.match_id = g.match_id WHERE m.season = 2024\nINTERSECT\nSELECT g.player_id FROM goals g JOIN matches m ON m.match_id = g.match_id WHERE m.season = 2025\nORDER BY player_id\nLIMIT 20;',
              fashion="SELECT customer_id FROM sales WHERE channel = 'Online' AND customer_id IS NOT NULL\nINTERSECT\nSELECT customer_id FROM sales WHERE channel = 'In-store' AND customer_id IS NOT NULL\nORDER BY customer_id;",
              politics='SELECT candidate_id FROM results WHERE election_id = 1\nINTERSECT\nSELECT candidate_id FROM results WHERE election_id = 3\nORDER BY candidate_id\nLIMIT 20;',
              finance="SELECT customer_id FROM accounts WHERE account_type = 'Savings'\nINTERSECT\nSELECT customer_id FROM accounts WHERE account_type = 'Current'\nORDER BY customer_id;",
              healthcare='SELECT a.patient_id FROM appointments a JOIN doctors d ON d.doctor_id = a.doctor_id WHERE d.department_id = 3\nINTERSECT\nSELECT a.patient_id FROM appointments a JOIN doctors d ON d.doctor_id = a.doctor_id WHERE d.department_id = 5\nORDER BY patient_id;')),
  dict(title='Recursive CTE: walk a hierarchy', level='Hard',
       explanation='A recursive CTE has two parts joined by UNION ALL: an anchor that picks the top rows, and a recursive step that joins back to the CTE to find the next level. It stops when a step finds no new rows.',
       tryIt='Start the anchor from a different person and see only their branch of the tree.',
       v=dict(sales="WITH RECURSIVE org AS (\n    SELECT employee_id, first_name, job_title, manager_id, 1 AS level\n    FROM employees WHERE manager_id IS NULL\n  UNION ALL\n    SELECT e.employee_id, e.first_name, e.job_title, e.manager_id, org.level + 1\n    FROM employees e JOIN org ON e.manager_id = org.employee_id\n)\nSELECT employee_id, first_name, job_title, level\nFROM org\nORDER BY level, employee_id;",
              sport="WITH RECURSIVE chain AS (\n    SELECT staff_id, first_name, role, reports_to, 1 AS level\n    FROM staff WHERE reports_to IS NULL AND team_id = 1\n  UNION ALL\n    SELECT s.staff_id, s.first_name, s.role, s.reports_to, chain.level + 1\n    FROM staff s JOIN chain ON s.reports_to = chain.staff_id\n)\nSELECT staff_id, first_name, role, level\nFROM chain\nORDER BY level, staff_id;",
              fashion="WITH RECURSIVE org AS (\n    SELECT staff_id, first_name, role, manager_id, 1 AS level\n    FROM staff WHERE manager_id IS NULL\n  UNION ALL\n    SELECT s.staff_id, s.first_name, s.role, s.manager_id, org.level + 1\n    FROM staff s JOIN org ON s.manager_id = org.staff_id\n)\nSELECT staff_id, first_name, role, level\nFROM org\nORDER BY level, staff_id;",
              politics="WITH RECURSIVE lineage AS (\n    SELECT party_id, party_name, split_from_party_id, 1 AS generation\n    FROM parties WHERE split_from_party_id IS NULL\n  UNION ALL\n    SELECT p.party_id, p.party_name, p.split_from_party_id, l.generation + 1\n    FROM parties p JOIN lineage l ON p.split_from_party_id = l.party_id\n)\nSELECT party_id, party_name, generation\nFROM lineage\nORDER BY generation, party_id;",
              finance="WITH RECURSIVE org AS (\n    SELECT employee_id, first_name, role, manager_id, 1 AS level\n    FROM employees WHERE manager_id IS NULL\n  UNION ALL\n    SELECT e.employee_id, e.first_name, e.role, e.manager_id, org.level + 1\n    FROM employees e JOIN org ON e.manager_id = org.employee_id\n)\nSELECT employee_id, first_name, role, level\nFROM org\nORDER BY level, employee_id\nLIMIT 15;",
              healthcare="WITH RECURSIVE org AS (\n    SELECT doctor_id, last_name, specialty, supervisor_id, 1 AS level\n    FROM doctors WHERE supervisor_id IS NULL\n  UNION ALL\n    SELECT d.doctor_id, d.last_name, d.specialty, d.supervisor_id, org.level + 1\n    FROM doctors d JOIN org ON d.supervisor_id = org.doctor_id\n)\nSELECT doctor_id, last_name, specialty, level\nFROM org\nORDER BY level, doctor_id;")),
 ],
 exercises=[
  dict(level='Easy', concepts=['CTE'], order=True,
       hint2='Start with WITH name AS ( ...the grouped query... ), then SELECT from name and filter with WHERE.',
       explain='The CTE builds one total per item, and the main query filters those totals. Splitting the steps makes each one easy to read and test.',
       v=dict(
        sales=('Finance wants the large orders.', 'Using a CTE, calculate revenue per order (quantity x unit price x (1 - discount)) and return only orders with revenue above 800. Return order id and revenue rounded to 2 decimals, highest first.', ['order_id', 'revenue'], 'WITH order_revenue AS (\n    SELECT order_id, SUM(quantity * unit_price * (1 - discount)) AS revenue\n    FROM order_items\n    GROUP BY order_id\n)\nSELECT order_id, ROUND(revenue, 2) AS revenue\nFROM order_revenue\nWHERE revenue > 800\nORDER BY revenue DESC;'),
        sport=('Broadcasters want the highest-scoring games.', 'Using a CTE, calculate total goals per match (home + away) and return matches with 7 or more goals. Return match id, match date and total_goals, most goals first, then match date.', ['match_id', 'match_date', 'total_goals'], 'WITH match_goals AS (\n    SELECT match_id, match_date, home_goals + away_goals AS total_goals\n    FROM matches\n)\nSELECT match_id, match_date, total_goals\nFROM match_goals\nWHERE total_goals >= 7\nORDER BY total_goals DESC, match_date;'),
        fashion=('Finance wants the large baskets.', 'Using a CTE, calculate revenue per sale (qty x unit price x (1 - discount)) and return sales above 600. Return sale id and revenue rounded to 2 decimals, highest first.', ['sale_id', 'revenue'], 'WITH sale_revenue AS (\n    SELECT sale_id, SUM(qty * unit_price * (1 - discount)) AS revenue\n    FROM sale_lines\n    GROUP BY sale_id\n)\nSELECT sale_id, ROUND(revenue, 2) AS revenue\nFROM sale_revenue\nWHERE revenue > 600\nORDER BY revenue DESC;'),
        politics=('The commission wants the parties that passed 100,000 votes in 2025.', 'Using a CTE, total the votes per party in election 3 (leave out independents) and return parties above 100,000 votes. Return party id and votes, most first.', ['party_id', 'votes'], 'WITH party_votes AS (\n    SELECT c.party_id, SUM(r.votes) AS votes\n    FROM results r\n    JOIN candidates c ON c.candidate_id = r.candidate_id\n    WHERE r.election_id = 3 AND c.party_id IS NOT NULL\n    GROUP BY c.party_id\n)\nSELECT party_id, votes\nFROM party_votes\nWHERE votes > 100000\nORDER BY votes DESC;'),
        finance=('Collections wants loans where more than 4,000,000 has already come back.', 'Using a CTE, total the amount paid per loan and return loans with more than 4,000,000 repaid. Return loan id and total_repaid rounded to 2 decimals, highest first.', ['loan_id', 'total_repaid'], 'WITH repaid AS (\n    SELECT loan_id, SUM(amount_paid) AS total_repaid\n    FROM repayments\n    GROUP BY loan_id\n)\nSELECT loan_id, ROUND(total_repaid, 2) AS total_repaid\nFROM repaid\nWHERE total_repaid > 4000000\nORDER BY total_repaid DESC;'),
        healthcare=('Pharmacy wants the visits with the most expensive prescriptions.', 'Using a CTE, total the prescription cost per appointment and return appointments with more than 70 in medicine costs. Return appointment id and medicine_cost rounded to 2 decimals, highest first, then appointment id.', ['appointment_id', 'medicine_cost'], 'WITH visit_cost AS (\n    SELECT appointment_id, SUM(cost) AS medicine_cost\n    FROM prescriptions\n    GROUP BY appointment_id\n)\nSELECT appointment_id, ROUND(medicine_cost, 2) AS medicine_cost\nFROM visit_cost\nWHERE medicine_cost > 70\nORDER BY medicine_cost DESC, appointment_id;'))),
  dict(level='Easy', concepts=['UNION'], order=True,
       hint2="Write two SELECTs with the same columns, each with its own label as a text column, and join them with UNION. Put ORDER BY once, at the very end.",
       explain='Each half of the UNION finds one kind of row and labels it. UNION removes exact duplicates; a row that qualifies for both labels appears once per label, because the label makes it different.',
       v=dict(
        sales=('The product team wants one watch list.', "Build one list of products priced over 150, labelled 'Premium', plus products with fewer than 40 in stock, labelled 'Low stock'. Return product name and flag, sorted by flag, then product name.", ['product_name', 'flag'], "SELECT product_name, 'Premium' AS flag FROM products WHERE unit_price > 150\nUNION\nSELECT product_name, 'Low stock' FROM products WHERE stock_quantity < 40\nORDER BY flag, product_name;"),
        sport=('Scouts want one list of players to watch.', "Build one list of players valued over 10,000,000, labelled 'High value', plus players born on or after 2005-01-01, labelled 'Young'. Return first name, last name and flag, sorted by flag, then last name, then first name.", ['first_name', 'last_name', 'flag'], "SELECT first_name, last_name, 'High value' AS flag FROM players WHERE market_value_usd > 10000000\nUNION\nSELECT first_name, last_name, 'Young' FROM players WHERE birth_date >= '2005-01-01'\nORDER BY flag, last_name, first_name;"),
        fashion=('The buying team wants one product watch list.', "Build one list of products priced over 180, labelled 'Luxury', plus products with a margin (retail - cost) under 10, labelled 'Thin margin'. Return product name and flag, sorted by flag, then product name.", ['product_name', 'flag'], "SELECT product_name, 'Luxury' AS flag FROM products WHERE retail_price > 180\nUNION\nSELECT product_name, 'Thin margin' FROM products WHERE retail_price - cost_price < 10\nORDER BY flag, product_name;"),
        politics=('The commission wants one list of seats needing special planning.', "Build one list of constituencies with more than 90,000 registered voters, labelled 'Large seat', plus those with fewer than 45,000, labelled 'Small seat'. Return constituency name and flag, sorted by flag, then name.", ['constituency_name', 'flag'], "SELECT constituency_name, 'Large seat' AS flag FROM constituencies WHERE registered_voters > 90000\nUNION\nSELECT constituency_name, 'Small seat' FROM constituencies WHERE registered_voters < 45000\nORDER BY flag, constituency_name;"),
        finance=('Risk wants one customer watch list.', "Build one list of customers with a credit score below 520, labelled 'Low score', plus customers who have a loan with status 'Defaulted', labelled 'Defaulted loan'. Return first name, last name and flag, sorted by flag, then last name, then first name.", ['first_name', 'last_name', 'flag'], "SELECT first_name, last_name, 'Low score' AS flag FROM customers WHERE credit_score < 520\nUNION\nSELECT c.first_name, c.last_name, 'Defaulted loan'\nFROM customers c JOIN loans l ON l.customer_id = c.customer_id\nWHERE l.status = 'Defaulted'\nORDER BY flag, last_name, first_name;"),
        healthcare=('Care coordinators want one patient watch list.', "Build one list of patients born before 1945, labelled 'Elderly', plus patients with 12 or more appointments, labelled 'Frequent'. Return first name, last name and flag, sorted by flag, then last name, then first name.", ['first_name', 'last_name', 'flag'], "SELECT first_name, last_name, 'Elderly' AS flag FROM patients WHERE birth_year < 1945\nUNION\nSELECT p.first_name, p.last_name, 'Frequent'\nFROM patients p JOIN appointments a ON a.patient_id = p.patient_id\nGROUP BY p.patient_id, p.first_name, p.last_name\nHAVING COUNT(*) >= 12\nORDER BY flag, last_name, first_name;"))),
  dict(level='Medium', concepts=['Chained CTEs', 'Share of total'], order=True,
       hint2='CTE 1 builds a total per group. CTE 2 adds those up into one grand total. The final query CROSS JOINs them and divides, multiplying by 100.0 for a percentage.',
       explain='The first CTE gives one row per group, the second gives one grand total, and CROSS JOIN puts that total next to every group so each share can be worked out.',
       v=dict(
        sales=('The board wants each category\'s share of revenue.', 'Using two CTEs, calculate revenue per category name and each category\'s percentage of total revenue. Return category name, revenue (2 decimals) and pct_of_total (1 decimal), highest revenue first.', ['category_name', 'revenue', 'pct_of_total'], 'WITH cat_rev AS (\n    SELECT cat.category_name, SUM(oi.quantity * oi.unit_price * (1 - oi.discount)) AS revenue\n    FROM order_items oi\n    JOIN products p ON p.product_id = oi.product_id\n    JOIN categories cat ON cat.category_id = p.category_id\n    GROUP BY cat.category_name\n),\ntotal AS (\n    SELECT SUM(revenue) AS all_revenue FROM cat_rev\n)\nSELECT cr.category_name, ROUND(cr.revenue, 2) AS revenue,\n       ROUND(100.0 * cr.revenue / t.all_revenue, 1) AS pct_of_total\nFROM cat_rev cr CROSS JOIN total t\nORDER BY cr.revenue DESC;'),
        sport=("The league wants each club's share of 2025 goals.", "Using CTEs, count goals scored by each team in the 2025 season, home and away (home_goals when they were the home team, away_goals when away), and each team's percentage of all goals. Return team name, goals and pct_of_league (1 decimal), most goals first, then team name.", ['team_name', 'goals', 'pct_of_league'], 'WITH team_goals AS (\n    SELECT home_team_id AS team_id, home_goals AS goals FROM matches WHERE season = 2025\n    UNION ALL\n    SELECT away_team_id, away_goals FROM matches WHERE season = 2025\n),\nper_team AS (\n    SELECT team_id, SUM(goals) AS goals FROM team_goals GROUP BY team_id\n),\ntotal AS (\n    SELECT SUM(goals) AS all_goals FROM per_team\n)\nSELECT t.team_name, pt.goals, ROUND(100.0 * pt.goals / tot.all_goals, 1) AS pct_of_league\nFROM per_team pt\nJOIN teams t ON t.team_id = pt.team_id\nCROSS JOIN total tot\nORDER BY pt.goals DESC, t.team_name;'),
        fashion=('The board wants each brand\'s share of revenue.', 'Using two CTEs, calculate revenue per brand name and each brand\'s percentage of total revenue. Return brand name, revenue (2 decimals) and pct_of_total (1 decimal), highest revenue first.', ['brand_name', 'revenue', 'pct_of_total'], 'WITH brand_rev AS (\n    SELECT b.brand_name, SUM(l.qty * l.unit_price * (1 - l.discount)) AS revenue\n    FROM sale_lines l\n    JOIN products p ON p.product_id = l.product_id\n    JOIN collections c ON c.collection_id = p.collection_id\n    JOIN brands b ON b.brand_id = c.brand_id\n    GROUP BY b.brand_name\n),\ntotal AS (\n    SELECT SUM(revenue) AS all_revenue FROM brand_rev\n)\nSELECT br.brand_name, ROUND(br.revenue, 2) AS revenue,\n       ROUND(100.0 * br.revenue / t.all_revenue, 1) AS pct_of_total\nFROM brand_rev br CROSS JOIN total t\nORDER BY br.revenue DESC;'),
        politics=('The commission is publishing national vote shares for 2025.', 'Using two CTEs, total votes per party name in election 3 (leave out independents) and each party\'s percentage of all party votes. Return party name, votes and vote_share_pct (1 decimal), most votes first.', ['party_name', 'votes', 'vote_share_pct'], 'WITH party_votes AS (\n    SELECT p.party_name, SUM(r.votes) AS votes\n    FROM results r\n    JOIN candidates c ON c.candidate_id = r.candidate_id\n    JOIN parties p ON p.party_id = c.party_id\n    WHERE r.election_id = 3\n    GROUP BY p.party_name\n),\ntotal AS (\n    SELECT SUM(votes) AS all_votes FROM party_votes\n)\nSELECT pv.party_name, pv.votes, ROUND(100.0 * pv.votes / t.all_votes, 1) AS vote_share_pct\nFROM party_votes pv CROSS JOIN total t\nORDER BY pv.votes DESC;'),
        finance=('The board wants each product\'s share of lending.', 'Using two CTEs, total principal per loan product and each product\'s percentage of all principal lent. Return product, total_principal and pct_of_total (1 decimal), largest first.', ['product', 'total_principal', 'pct_of_total'], 'WITH by_product AS (\n    SELECT product, SUM(principal) AS total_principal\n    FROM loans GROUP BY product\n),\ntotal AS (\n    SELECT SUM(total_principal) AS all_principal FROM by_product\n)\nSELECT bp.product, bp.total_principal,\n       ROUND(100.0 * bp.total_principal / t.all_principal, 1) AS pct_of_total\nFROM by_product bp CROSS JOIN total t\nORDER BY bp.total_principal DESC;'),
        healthcare=('The board wants each department\'s share of completed visits.', "Using two CTEs, count completed appointments per department name and each department's percentage of all completed appointments. Return department name, visits and pct_of_total (1 decimal), most visits first.", ['department_name', 'visits', 'pct_of_total'], "WITH dept AS (\n    SELECT dp.department_name, COUNT(*) AS visits\n    FROM appointments a\n    JOIN doctors d ON d.doctor_id = a.doctor_id\n    JOIN departments dp ON dp.department_id = d.department_id\n    WHERE a.status = 'Completed'\n    GROUP BY dp.department_name\n),\ntotal AS (\n    SELECT SUM(visits) AS all_visits FROM dept\n)\nSELECT d.department_name, d.visits, ROUND(100.0 * d.visits / t.all_visits, 1) AS pct_of_total\nFROM dept d CROSS JOIN total t\nORDER BY d.visits DESC;"))),
  dict(level='Medium', concepts=['INTERSECT', 'EXCEPT'], order=True,
       hint2='Write one SELECT for each group, returning the same id column, and put INTERSECT (in both) or EXCEPT (in the first but not the second) between them.',
       explain='Set operations compare whole rows. INTERSECT keeps ids that appear in both lists; EXCEPT keeps those in the first list only. Duplicates are removed automatically.',
       v=dict(
        sales=('Marketing wants cross-category shoppers.', 'Using INTERSECT, find customers who bought from both category 1 and category 5. Return customer id, sorted ascending.', ['customer_id'], 'SELECT o.customer_id\nFROM orders o\nJOIN order_items oi ON oi.order_id = o.order_id\nJOIN products p ON p.product_id = oi.product_id\nWHERE p.category_id = 1\nINTERSECT\nSELECT o.customer_id\nFROM orders o\nJOIN order_items oi ON oi.order_id = o.order_id\nJOIN products p ON p.product_id = oi.product_id\nWHERE p.category_id = 5\nORDER BY customer_id;'),
        sport=("Coaches want players whose scoring dried up.", 'Using EXCEPT, find players who scored in the 2024 season but not in the 2025 season. Return player id, sorted ascending.', ['player_id'], 'SELECT g.player_id\nFROM goals g JOIN matches m ON m.match_id = g.match_id\nWHERE m.season = 2024\nEXCEPT\nSELECT g.player_id\nFROM goals g JOIN matches m ON m.match_id = g.match_id\nWHERE m.season = 2025\nORDER BY player_id;'),
        fashion=('The digital team wants customers who shop in both channels.', "Using INTERSECT, find customers who bought both 'Online' and 'In-store' in 2025 (sale date on or after 2025-01-01). Return customer id, sorted ascending.", ['customer_id'], "SELECT customer_id FROM sales WHERE channel = 'Online' AND customer_id IS NOT NULL AND sale_date >= '2025-01-01'\nINTERSECT\nSELECT customer_id FROM sales WHERE channel = 'In-store' AND customer_id IS NOT NULL AND sale_date >= '2025-01-01'\nORDER BY customer_id;"),
        politics=('A historian is tracking candidates who stood again.', 'Using INTERSECT, find candidates who stood in both election 1 and election 3 in region 1 (constituencies 1 to 5). Return candidate id, sorted ascending.', ['candidate_id'], 'SELECT candidate_id FROM results WHERE election_id = 1 AND constituency_id BETWEEN 1 AND 5\nINTERSECT\nSELECT candidate_id FROM results WHERE election_id = 3 AND constituency_id BETWEEN 1 AND 5\nORDER BY candidate_id;'),
        finance=('Product wants customers who hold both account types.', "Using INTERSECT, find customers who have both a 'Savings' and a 'Current' account. Return customer id, sorted ascending.", ['customer_id'], "SELECT customer_id FROM accounts WHERE account_type = 'Savings'\nINTERSECT\nSELECT customer_id FROM accounts WHERE account_type = 'Current'\nORDER BY customer_id;"),
        healthcare=('Cardiology wants patients it shares with Orthopaedics.', 'Using INTERSECT, find patients who have had appointments in both department 3 (Cardiology) and department 5 (Orthopaedics). Return patient id, sorted ascending.', ['patient_id'], 'SELECT a.patient_id FROM appointments a JOIN doctors d ON d.doctor_id = a.doctor_id WHERE d.department_id = 5\nINTERSECT\nSELECT a.patient_id FROM appointments a JOIN doctors d ON d.doctor_id = a.doctor_id WHERE d.department_id = 3\nORDER BY patient_id;'))),
  dict(level='Hard', concepts=['Recursive CTE'], order=True,
       hint2='Anchor: the top rows (where the parent column IS NULL), with level 1 and the name as the path. Recursive step: join the table to the CTE on parent = CTE id, adding 1 to level and appending to the path with CONCAT.',
       explain='The anchor finds the top of the tree. Each pass of the recursive step finds the next level down, carrying the level number and the growing path with it, until no new rows are found.',
       v=dict(
        sales=('HR wants the full org chart.', "Using a recursive CTE, list every employee with their level (1 for the person with no manager) and their reporting path, such as 'Laura > Marcus > Diego' using first names. Return first name, level and path, sorted by path.", ['first_name', 'level', 'path'], "WITH RECURSIVE org AS (\n    SELECT employee_id, first_name, 1 AS level, CAST(first_name AS CHAR(200)) AS path\n    FROM employees WHERE manager_id IS NULL\n  UNION ALL\n    SELECT e.employee_id, e.first_name, org.level + 1, CONCAT(org.path, ' > ', e.first_name)\n    FROM employees e JOIN org ON e.manager_id = org.employee_id\n)\nSELECT first_name, level, path\nFROM org\nORDER BY path;"),
        sport=("Team 1 wants its backroom chain of command.", "Using a recursive CTE, list team 1's staff with their level (1 for the person who reports to nobody) and their reporting path of first names, such as 'A > B > C'. Return first name, role, level and path, sorted by path.", ['first_name', 'role', 'level', 'path'], "WITH RECURSIVE chain AS (\n    SELECT staff_id, first_name, role, 1 AS level, CAST(first_name AS CHAR(200)) AS path\n    FROM staff WHERE reports_to IS NULL AND team_id = 1\n  UNION ALL\n    SELECT s.staff_id, s.first_name, s.role, chain.level + 1, CONCAT(chain.path, ' > ', s.first_name)\n    FROM staff s JOIN chain ON s.reports_to = chain.staff_id\n)\nSELECT first_name, role, level, path\nFROM chain\nORDER BY path;"),
        fashion=('HR wants the full retail org chart.', "Using a recursive CTE, list every staff member with their level (1 for the person with no manager) and their reporting path of first names, such as 'A > B > C'. Return first name, role, level and path, sorted by path.", ['first_name', 'role', 'level', 'path'], "WITH RECURSIVE org AS (\n    SELECT staff_id, first_name, role, 1 AS level, CAST(first_name AS CHAR(200)) AS path\n    FROM staff WHERE manager_id IS NULL\n  UNION ALL\n    SELECT s.staff_id, s.first_name, s.role, org.level + 1, CONCAT(org.path, ' > ', s.first_name)\n    FROM staff s JOIN org ON s.manager_id = org.staff_id\n)\nSELECT first_name, role, level, path\nFROM org\nORDER BY path;"),
        politics=('A historian is mapping how parties split.', "Using a recursive CTE, list every party with its generation (1 for parties that split from nobody) and its lineage, such as 'Blue Party > Teal Party'. Return party name, generation and lineage, sorted by lineage.", ['party_name', 'generation', 'lineage'], "WITH RECURSIVE lineage AS (\n    SELECT party_id, party_name, 1 AS generation, CAST(party_name AS CHAR(200)) AS lineage\n    FROM parties WHERE split_from_party_id IS NULL\n  UNION ALL\n    SELECT p.party_id, p.party_name, l.generation + 1, CONCAT(l.lineage, ' > ', p.party_name)\n    FROM parties p JOIN lineage l ON p.split_from_party_id = l.party_id\n)\nSELECT party_name, generation, lineage\nFROM lineage\nORDER BY lineage;"),
        finance=('HR wants the lending org chart for the Marina and Ikeja branches.', "Using a recursive CTE, list the Head of Lending and everyone below them in branches 1 and 2, with level (1 for the head) and the reporting path of first names. Start from the employee with no manager and only follow employees whose branch is 1 or 2. Return first name, role, level and path, sorted by path.", ['first_name', 'role', 'level', 'path'], "WITH RECURSIVE org AS (\n    SELECT employee_id, first_name, role, 1 AS level, CAST(first_name AS CHAR(200)) AS path\n    FROM employees WHERE manager_id IS NULL\n  UNION ALL\n    SELECT e.employee_id, e.first_name, e.role, org.level + 1, CONCAT(org.path, ' > ', e.first_name)\n    FROM employees e JOIN org ON e.manager_id = org.employee_id\n    WHERE e.branch_id IN (1, 2)\n)\nSELECT first_name, role, level, path\nFROM org\nORDER BY path;"),
        healthcare=('The medical director wants the supervision tree.', "Using a recursive CTE, list every doctor with their level (1 for the doctor with no supervisor) and the supervision path of last names, such as 'A > B > C'. Return last name, specialty, level and path, sorted by path.", ['last_name', 'specialty', 'level', 'path'], "WITH RECURSIVE org AS (\n    SELECT doctor_id, last_name, specialty, 1 AS level, CAST(last_name AS CHAR(200)) AS path\n    FROM doctors WHERE supervisor_id IS NULL\n  UNION ALL\n    SELECT d.doctor_id, d.last_name, d.specialty, org.level + 1, CONCAT(org.path, ' > ', d.last_name)\n    FROM doctors d JOIN org ON d.supervisor_id = org.doctor_id\n)\nSELECT last_name, specialty, level, path\nFROM org\nORDER BY path;"))),
 ])
